package com.example.rokidkeyboardbridge;
import java.io.*;import org.json.*;
/** Export the metadata actually used by the selector; special renderers retain their independent posture states. */
public class ExportImageSceneMetadata {
 public static void main(String[] args)throws Exception{JSONObject root=new JSONObject().put("schema",1).put("version",687).put("provenance","existing reviewed catalog and decoder; no new visual anatomy certification");JSONArray entries=new JSONArray();
 for(FullBodyPoseCatalog.Pose p:FullBodyPoseCatalog.ALL){JSONArray emotions=new JSONArray();for(FullBodyPoseCatalog.Kind k:FullBodyPoseCatalog.Kind.values())if(p.supports(k))emotions.put(k.name());String asset=CoolSmilePolicy.supports(p.id)?"cool-smile-v561/frame-"+p.id+".png":FullBodyRealisticAssets.NAMES[FullBodyRealisticAssets.SHEET[p.id]];int[] box=FullBodyRealisticAssets.REGIONS[p.id];entries.put(new JSONObject().put("id",p.id).put("asset",asset).put("crop",CoolSmilePolicy.supports(p.id)?JSONObject.NULL:new JSONArray(box)).put("decodeMode",CoolSmilePolicy.supports(p.id)?"WHOLE_IMAGE":"REGION").put("posture",ConversationImageMetadata.posture(p)).put("emotions",emotions).put("intensity",p.intensity).put("gesture",p.gesture).put("scene",ConversationImageMetadata.scene(p)).put("automaticIdleCandidate",ConversationImageMetadata.spontaneous(p)).put("avoidWhen",ConversationImageMetadata.avoid(p)).put("transitionGroup",ConversationImageMetadata.posture(p)).put("onMissingMatch","KEEP_CURRENT_POSTURE"));}
 root.put("bodyPoses",entries);JSONArray frames=new JSONArray();for(int id=0;id<FullBodyRealisticAssets.REGIONS.length;id++){boolean override=CoolSmilePolicy.supports(id);String asset=override?"cool-smile-v561/frame-"+id+".png":FullBodyRealisticAssets.NAMES[FullBodyRealisticAssets.SHEET[id]];frames.put(new JSONObject().put("frameId",id).put("asset",asset).put("crop",override?JSONObject.NULL:new JSONArray(FullBodyRealisticAssets.REGIONS[id])).put("role",role(id)).put("selection",id<181?"SEMANTIC_POSE":"OWNING_SEQUENCE_ONLY").put("automaticEmotionInference",false));}root.put("sourceFrames",frames);
 JSONArray portraits=new JSONArray();String[] faces={"NEUTRAL","LISTEN","BRIEF_ACK","JOY","THINK","EXPLAIN","SURPRISE","WARMTH","LISTEN_FRONT","LISTEN_SIDE","NOD","ACK","OFFER_HAND","HOLD_HAND","REOFFER_HAND","SETTLE_CONTACT","NOTEBOOK_READY","NOTEBOOK_WRITE","NOTEBOOK_WRITE_ALT","NOTEBOOK_CLOSE","SPEAK","SPEAK_SMILE","SETTLE","LISTEN_RETURN"};for(int i=0;i<faces.length;i++)portraits.put(new JSONObject().put("asset","loki_identity_portraits_v686.png").put("cell",i).put("columns",4).put("rows",6).put("scene",faces[i]).put("avoidWhen","UNMATCHED_NEGATIVE_EMOTION").put("faceBlendMs",240));root.put("portraitFaces",portraits);
 JSONArray gestures=new JSONArray();for(int i=0;i<44;i++)gestures.put(new JSONObject().put("clip",i).put("asset",FullBodyGestureRenderer.assetForClip(i)).put("owner","FullBodyGestureRenderer").put("selection","EXISTING_SCENE_POLICY_ONLY").put("avoidWhen","UNMATCHED_POSTURE|REFUSAL|NAVIGATION|RECORDING"));root.put("gestureClips",gestures);root.put("postureBridge",new JSONObject().put("asset",PostureBridgeRenderer.ASSET).put("columns",3).put("rowBoundaries",new JSONArray(new int[]{0,460,1024})).put("frames",6).put("durationMs",PostureBridgeRenderer.DURATION).put("fixedPersonScale",true).put("selection","POSTURE_CHANGE_ONLY").put("avoidWhen","NAVIGATION|RECORDING"));
JSONArray rest=new JSONArray();String[] names={"SUPINE","ROLL","STRETCH","SMALL_SHIFT","WAVE","KNEES_RAISED","LOWER_LEGS","KNEE_SHIFT","SEATED_KNEE_HUG","PRONE_READING","SIDE_REST","SEATED_STRETCH","OFFDUTY_PILLOW","OFFDUTY_ARMS_BACK","OFFDUTY_CHEEK","RESTLESS_SLEEP_DREAM","SMALL_RELAXED_LEG_GAP"};for(int i=0;i<names.length;i++)rest.put(new JSONObject().put("motion",i).put("scene",names[i]).put("renderer",i<8?"RestArtworkRenderer":"ComfortPoseRenderer").put("asset",new String[]{"loki_rest_master_v675.png","loki_rest_motion_v675.png","loki_rest_motion_v675.png","loki_rest_motion_v675.png","loki_rest_wave_v675.png","loki_rest_knee_v676.png","loki_rest_knee_v676.png","loki_rest_knee_v676.png","loki_comfort_hug_v678.png","loki_comfort_read_v678.png","loki_comfort_side_v678.png","loki_comfort_stretch_v678.png","loki_offduty_pillow_v683.png","loki_offduty_arms_v683.png","loki_offduty_chin_v683.png","loki_offduty_dream_v683.png","loki_rest_relaxed_legs_v684.png"}[i]).put("posture",i==8||i==11?"SEATED":"LYING").put("avoidWhen","NAVIGATION|RECORDING|EXPLICIT_FIXED_POSE").put("faceBlendMs",260).put("canvasWidth",512).put("canvasHeight",768).put("framing",i>=12?"PORTRAIT_DIRECTLY_OVERHEAD":"LEGACY").put("barefoot",i>=12));root.put("restMotions",rest).put("emotionSelection","MATCH_CURRENT_POSTURE_FIRST").put("safetyPriority","REFUSAL_ENDS_CONTACT").put("runtimeFileReadsPerFrame",0);if(args.length>1){try(java.util.zip.ZipFile apk=new java.util.zip.ZipFile(args[1])){for(int i=0;i<frames.length();i++)if(apk.getEntry("assets/"+frames.getJSONObject(i).getString("asset"))==null)throw new IllegalStateException("Missing indexed frame asset "+i);for(int i=0;i<gestures.length();i++)if(apk.getEntry("assets/"+gestures.getJSONObject(i).getString("asset"))==null)throw new IllegalStateException("Missing indexed gesture asset "+i);for(int i=0;i<rest.length();i++)if(apk.getEntry("assets/"+rest.getJSONObject(i).getString("asset"))==null)throw new IllegalStateException("Missing indexed rest asset "+i);}}
 try(Writer out=new OutputStreamWriter(new FileOutputStream(args[0]),"UTF-8")){out.write(root.toString(2));}}
 static String role(int id){if(id<181)return "SEMANTIC_POSE";if(id<=185)return "SEATED_IDLE_SEQUENCE";if(id<=191)return "SIT_TRANSITION";if(id<=197)return "STAND_TRANSITION";for(int i=0;i<FullBodyPoseLinks.PAIRS.length;i++)for(int f:FullBodyPoseLinks.frames(i))if(f==id)return "POSE_LINK_"+FullBodyPoseLinks.PAIRS[i][0]+"_"+FullBodyPoseLinks.PAIRS[i][1];for(int i=0;i<6;i++)for(int f:FullBodyIdleActivity.frames(i))if(f==id)return new String[]{"SEATED_TABLET","SEATED_COFFEE","SEATED_PEN_EXPLICIT","STANDING_PEN_EXPLICIT","STANDING_PLANNER","SEATED_PLANNER"}[i];for(int f:FullBodyPerformancePolicy.frames())if(f==id)return "EXPLICIT_PERFORMANCE";for(int i=0;i<5;i++)for(int f:FullBodyConversationMotion.frames(i))if(f==id)return new String[]{"SEATED_SURPRISE","SEATED_JOY","TEARS","THOUGHT_DAYDREAM","THOUGHT_RECALL"}[i];if(FullBodyCyberMotion.groupForPose(id)>=0)return "DEDICATED_SCENE_"+FullBodyCyberMotion.groupForPose(id);return "DEDICATED_ANIMATION_ONLY";}
}
